"""Build an atomic, content-versioned offline shell from distributable files."""
from pathlib import Path
import hashlib,json
root=Path(__file__).resolve().parent.parent
files=['index.html','style.css','core.js','app.js','manifest.webmanifest','data/curriculum.json']+[str(p.relative_to(root)) for p in sorted((root/'assets').rglob('*')) if p.is_file() and p.suffix!='.json' and p.name!='garden-paper.png']
version=hashlib.sha256(b''.join((root/p).read_bytes() for p in files)).hexdigest()[:16]
(root/'sw.js').write_text('''// Generated by tools/build_sw.py; rebuild after application/content changes.
const CACHE='mandarin-garden-'''+version+'''';
const FILES='''+json.dumps(['./']+['./'+p for p in files])+''';
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('message',event=>{if(event.data==='activate')self.skipWaiting()});
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('mandarin-garden-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.pathname.startsWith(new URL('./',self.location.href).pathname))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const hit=await cache.match(event.request,{ignoreSearch:true});if(hit)return hit;if(event.request.mode==='navigate')return cache.match('./index.html');return fetch(event.request)})())});
''')
print('Offline shell:',version,len(files),'files')
